use rust_rule_engine::{KnowledgeBase, Facts, Value};

let mut kb = KnowledgeBase::new("pricing");
kb.add_rule_from_string(r#"
    rule "volume-discount" salience 10 no-loop true {
        when  Order.Units > 100 && Order.LoyaltyYears > 2
        then  Order.Discount = 0.10;
    }
"#)?;
let mut facts = Facts::new();
facts.set("Order.Units", Value::Integer(250));
facts.set("Order.LoyaltyYears", Value::Integer(5));
kb.execute(&mut facts)?;
